import { cities } from "../cities.js";

<state|{ q }| {
  q: ""
}>

<let|filteredCities| cities.filter(city => 
  city.toLowerCase().includes(q.toLowerCase())
)>

<input 
  id="q"
  type="text"
  value=q
  on-input=(event) => {
    q = event.target.value;
  }
/>

<ul id="results">
  <for|city| of=filteredCities>
    <li>${city}</li>
  </for>
</ul>

<div id="count">${filteredCities.length} matches</div>

import { addEntry } from "../../store.js";

export async function post(request) {
  const formData = await request.formData();
  const message = formData.get('message')?.trim() || '';

  if (message) {
    addEntry(message);
  }

  return new Response(null, {
    status: 302,
    headers: { 'Location': '/guestbook' }
  });
}

import { addEntry } from "../store.js";

export default async (req, res) => {
  if (req.method === "POST") {
    const body = await new Promise((resolve, reject) => {
      let data = "";
      req.on("data", chunk => {
        data += chunk.toString();
      });
      req.on("end", () => resolve(data));
      req.on("error", reject);
    });

    const params = new URLSearchParams(body);
    const message = (params.get("message") || "").trim();

    if (message) {
      addEntry(message);
    }

    res.statusCode = 302;
    res.setHeader("Location", "/guestbook");
    res.end();
  }
};

import { entries, addEntry } from "../../store.js";

export const GET = Run.GET((context, next) => {
  return next({ entries });
});

export const POST = Run.POST(async (context) => {
  const form = await context.request.formData();
  const msg = String(form.get("message") || "").trim();
  if (msg) addEntry(msg);
  return context.redirect("/guestbook", 303);
});

